// CreateProjectWithBodyWithResponse Create a project or open a git repository as one
//
// source.type picks what happens:
//   - new: create an empty git repository at <path>/<name> (path defaults
//     to <home>/projects) and open it. An existing directory that is not
//     in a git repository is initialized in place. When the name is taken
//     or the directory is in a git repository, on_conflict "open" opens
//     that project instead and returns the conflict under "conflict";
//     without it the conflict is returned as the error.
//   - local: open the repository holding path. Worktrees and other clones
//     of a known repository join its project.
//   - git: open the project with that origin, or clone it into
//     <home>/projects/<name> if it is unknown.
//
// Opening a known project marks it open, drops its checkouts no longer
// on disk and relaunches the terminals closing it stopped, listing them
// under "started". When no checkout is left, on_missing_checkout
// "reclone" clones it again and "remove" removes it, which terminals
// still running refuse with project_in_use; without it checkout_missing
// is returned.
//
// Errors: checkout_missing, clone_failed, invalid_argument,
// invalid_name, invalid_path, name_taken, not_git_repo, path_exists,
// project_in_use, project_mismatch, repo_exists.
//
// Takes any type of body and a specified content type, and returns a wrapper object for the known response body format(s).
//
// Corresponds with POST /v1/projects (the `CreateProject` operationId).
func (c *ClientWithResponses) CreateProjectWithBodyWithResponse(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*CreateProjectResponse, error) {
	rsp, err := c.CreateProjectWithBody(ctx, contentType, body, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseCreateProjectResponse(rsp)
}

